import React from 'react';
import { useOutletContext, Outlet, useLocation } from 'react-router-dom';
import RealtimeWorkspace from '../../components/RealtimeWorkspace';
import ProjectNavbar from '../../components/ProjectNavbar';

const WorkspacePage = () => {
  const context = useOutletContext();
  const location = useLocation();
  const isDashboard = location.pathname === '/work';

  // 1. Destructure the setter for the 'work' channel
  const { setter: setWorkData } = context?.work || {};

  return (
    <div className="h-full">
      <ProjectNavbar basePath="work" links={["Streaming", "Collab", "Nodes", "Logs"]} />
      <div className="p-8">
         {/* 2. Pass the global setter into the dashboard */}
         {isDashboard && <RealtimeWorkspace setWorkspaceData={setWorkData} />}
         
         <Outlet context={context} /> 
      </div>
    </div>
  );
};

export default WorkspacePage;
